    Bug 1907440 - Fix regression in compose API: Do not report fcc folders instead of throwing, if accountsRead permission is missing. r=mkmelin


    The `folderManager` property does not exist in the `extension` object,
    unless the accountsRead permission is granted. We therefore need to
    check the permission before using it. This was forgotten in two places
    of the Compose API.

    Differential Revision: https://phabricator.services.mozilla.com/D216340

diff --git a/mail/components/extensions/parent/ext-compose.js b/mail/components/extensions/parent/ext-compose.js
index 79ed5a3282b..0cf7cf55a18 100644
--- a/mail/components/extensions/parent/ext-compose.js
+++ b/mail/components/extensions/parent/ext-compose.js
@@ -422,14 +422,22 @@ async function getComposeDetails(composeWindow, extension) {
     overrideDefaultFcc = true;
   }
   let overrideDefaultFccFolder = "";
-  if (overrideDefaultFcc && !composeFields.fcc.startsWith("nocopy://")) {
+  if (
+    extension.hasPermission("accountsRead") &&
+    overrideDefaultFcc &&
+    !composeFields.fcc.startsWith("nocopy://")
+  ) {
     const folder = MailUtils.getExistingFolder(composeFields.fcc);
     if (folder) {
       overrideDefaultFccFolder = extension.folderManager.convert(folder);
     }
   }
   let additionalFccFolder = "";
-  if (composeFields.fcc2 && !composeFields.fcc2.startsWith("nocopy://")) {
+  if (
+    extension.hasPermission("accountsRead") &&
+    composeFields.fcc2 &&
+    !composeFields.fcc2.startsWith("nocopy://")
+  ) {
     const folder = MailUtils.getExistingFolder(composeFields.fcc2);
     if (folder) {
       additionalFccFolder = extension.folderManager.convert(folder);
@@ -525,24 +533,24 @@ async function getComposeDetails(composeWindow, extension) {
     details.relatedMessageId = relatedMessageId;
   }

