-        const { folder } = getFolder(details.additionalFccFolder);
-        composeFields.fcc2 = folder.URI;
-      } else {
+      if (
+        details.additionalFccFolderId === null ||
+        details.additionalFccFolderId == ""
+      ) {
         composeFields.fcc2 = "";
+      } else if (details.additionalFccFolderId) {
